package task

func Allowed(count, limit int) bool {
	return count < limit
}

package task

import "testing"

func TestAllowedIncludesLimit(t *testing.T) {
	if !Allowed(5, 5) {
		t.Fatal("Allowed(5, 5) = false, want true")
	}
}

